// Checks the Cal.com signature (HMAC-SHA256 of the raw body, hex, header x-cal-signature-256)
// and turns the delivery into one booking record. Every other request is answered here.
const s = $('Booking Settings').first().json;
const req = $('Receive Cal.com Webhook').first().json;
const stop = (status, error) => [{ json: { accepted: false, status, response: { ok: false, error } } }];
const secret = String(s.webhook_secret ?? '').trim();
if (!secret) return stop(500, 'webhook_secret is empty in Booking Settings.');
const expected = String($('Sign Raw Body').first().json.expected_signature || '');
const got = String(req.headers['x-cal-signature-256'] ?? '').trim().toLowerCase();
let diff = got.length ^ expected.length;
for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ (got.charCodeAt(i) || 0);
if (!expected || diff !== 0) return stop(401, 'Missing or invalid x-cal-signature-256 signature.');

const b = req.body;
if (!b || typeof b !== 'object' || Array.isArray(b) || typeof b.triggerEvent !== 'string') return stop(400, 'Body is not a Cal.com webhook delivery.');
const actions = { BOOKING_CREATED: 'created', BOOKING_RESCHEDULED: 'rescheduled', BOOKING_CANCELLED: 'cancelled' };
const action = actions[b.triggerEvent];
if (!action) return [{ json: { accepted: false, status: 200, response: { ok: true, ignored: 'Event ' + b.triggerEvent.slice(0, 60) + ' is not handled.' } } }];
const p = b.payload && typeof b.payload === 'object' ? b.payload : {};
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const uid = str(p.uid);
if (!uid) return stop(400, 'payload.uid is missing.');
// Seated event types: every seat shares the booking uid and attendees[0] is not the new seat, so they are not stored.
if (str(p.attendeeSeatId) || Number(p.seatsPerTimeSlot) > 0) return [{ json: { accepted: false, status: 200, response: { ok: true, ignored: 'Seated event types are not supported; booking ' + uid.slice(0, 60) + ' was not stored.' } } }];
const iso = (v) => { const t = Date.parse(str(v)); return Number.isFinite(t) ? new Date(t).toISOString() : ''; };
const start = iso(p.startTime);
const attendees = Array.isArray(p.attendees) ? p.attendees.filter((a) => a && typeof a === 'object') : [];
const main = attendees[0] || {};
const email = str(main.email).toLowerCase();
if (action !== 'cancelled') {
  if (!start) return stop(400, 'payload.startTime is missing or not a date.');
  if (!email) return stop(400, 'payload.attendees[0].email is missing.');
  if (action === 'rescheduled' && !str(p.rescheduleUid)) return stop(400, 'payload.rescheduleUid is missing.');
}
const meeting = str(p.metadata && p.metadata.videoCallUrl) || (/^https:\/\//.test(str(p.location)) ? str(p.location) : '');
return [{ json: { accepted: true, action, booking: {
  uid,
  title: str(p.title).slice(0, 300),
  start_at: start,
  end_at: iso(p.endTime) || start,
  attendee_name: str(main.name).slice(0, 200),
  attendee_email: email,
  attendee_time_zone: str(main.timeZone),
  guest_emails: attendees.slice(1).map((a) => str(a.email).toLowerCase()).filter(Boolean).join(', '),
  organizer_email: str(p.organizer && p.organizer.email).toLowerCase(),
  meeting_url: meeting,
  rescheduled_from: action === 'rescheduled' ? str(p.rescheduleUid) : '',
  cancellation_reason: str(p.cancellationReason).slice(0, 500),
  booked_at: iso(b.createdAt) || new Date().toISOString(),
} } }];

// Finds booked meetings whose reminder is due and writes the email.
const s = $('Booking Settings').first().json;
const hours = (v, d) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Number(v) : d);
const first = hours(s.first_reminder_hours, 24) * 3600000;
const second = hours(s.second_reminder_hours, 1) * 3600000;
const now = Date.now();
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// If two copies of one booking were stored at the same moment, only the oldest row (lowest id) gets reminders.
const oldest = {};
for (const { json: b } of $input.all()) if (b.id !== undefined && b.uid && (oldest[b.uid] === undefined || b.id < oldest[b.uid])) oldest[b.uid] = b.id;
const out = [];
for (const { json: b } of $input.all()) {
  if (b.id === undefined || oldest[b.uid] !== b.id || b.status !== 'booked' || !b.attendee_email) continue;
  const start = new Date(b.start_at).getTime();
  const left = start - now;
  if (!Number.isFinite(start) || left <= 0) continue;
  const lead = start - new Date(b.booked_at).getTime(); // how far ahead it was booked or rescheduled
  const sent = Number(b.reminders_sent) || 0;
  let kind = 0;
  if (sent < 2 && left <= second && lead > second) kind = 2;
  else if (sent < 1 && left <= first && left > second && lead > first) kind = 1;
  if (!kind) continue;
  const zone = b.attendee_time_zone && DateTime.now().setZone(b.attendee_time_zone).isValid ? b.attendee_time_zone : $now.zoneName;
  const when = DateTime.fromMillis(start, { zone }).toFormat("cccc d LLLL yyyy 'at' HH:mm") + ' (' + zone + ')';
  const title = b.title || 'your meeting';
  const link = /^https:\/\//.test(b.meeting_url || '') ? '<p>Join here: <a href="' + esc(b.meeting_url) + '">' + esc(b.meeting_url) + '</a></p>' : '';
  out.push({ json: {
    row_id: b.id, uid: b.uid, kind, previous_sent: sent, to: b.attendee_email,
    subject: 'Reminder: ' + title + ' on ' + when,
    html: '<p>Hi ' + esc(b.attendee_name || 'there') + ',</p><p>This is a reminder of <b>' + esc(title) + '</b> on ' + esc(when) + '.</p>' + link + '<p>See you soon.</p>',
  } });
}
return out;
